CREATE TABLE IF NOT EXISTS subcontract_boq_items(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,subcontract_boq_section_id BIGINT UNSIGNED NOT NULL,cost_code_id BIGINT UNSIGNED NULL,item_code VARCHAR(50) NULL,description VARCHAR(1000) NOT NULL,unit_id BIGINT UNSIGNED NULL,unit_name VARCHAR(100) NULL,unit_symbol VARCHAR(30) NULL,quantity DECIMAL(18,4) NULL,unit_rate DECIMAL(18,2) NULL,line_total DECIMAL(18,2) GENERATED ALWAYS AS(ROUND(quantity*unit_rate,2)) STORED,sort_order INT UNSIGNED NOT NULL,notes TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_subcontract_boq_items_order(subcontract_boq_section_id,sort_order),CONSTRAINT fk_subcontract_boq_items_section FOREIGN KEY(subcontract_boq_section_id) REFERENCES subcontract_boq_sections(id) ON DELETE RESTRICT,CONSTRAINT fk_subcontract_boq_items_cost FOREIGN KEY(cost_code_id) REFERENCES cost_codes(id) ON DELETE RESTRICT,CONSTRAINT fk_subcontract_boq_items_unit FOREIGN KEY(unit_id) REFERENCES units(id) ON DELETE RESTRICT,CONSTRAINT chk_subcontract_boq_items_values CHECK((quantity IS NULL OR quantity>=0) AND(unit_rate IS NULL OR unit_rate>=0)),CONSTRAINT chk_subcontract_boq_items_sort CHECK(sort_order>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
